// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _test(address sender, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(amount < c.MinDeposit());
        uint256 prevBal;
        try c.balances(sender) returns (uint256 __r) { prevBal = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 newBal;
        try c.balances(sender) returns (uint256 __r) { newBal = __r; } catch { return; }
        assertTrue(newBal == prevBal);
    }

    function testFuzz_test(address sender, uint256 amount) public {
        _test(sender, amount);
    }

    receive() external payable {}
}
